UPDATE pcd_share_link_table
SET share_status = 'revoked'
WHERE share_id = #{share_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND share_owner_id = #{owner_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND share_status = 'active'

UPDATE pcd_share_link_table
SET share_view_count = share_view_count + 1
WHERE share_id = #{share_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
